-- The shop, as the Oracle tests seed it (Oracle's free container in CI): the same rows as shop.sqlite, with what
-- Oracle can say about itself (identity keys, comments, a unique email, an index, NUMBER scales, a view). Names are
-- unquoted, so Oracle keeps them in upper case; active is a NUMBER(1), as Oracle had no BOOLEAN before 23ai. One
-- statement per block, as scripts/seed-oracle.mjs runs them.
CREATE TABLE customers (
  id NUMBER(10) GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  name VARCHAR2(100) NOT NULL,
  email VARCHAR2(255) UNIQUE,
  signed_up DATE,
  active NUMBER(1) DEFAULT 1 NOT NULL
);
COMMENT ON TABLE customers IS 'People who have ordered';
COMMENT ON COLUMN customers.email IS 'Lower case';
CREATE TABLE orders (
  id NUMBER(10) GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  customer_id NUMBER(10) NOT NULL,
  total NUMBER(10, 2),
  placed_at TIMESTAMP,
  status VARCHAR2(10) DEFAULT 'placed' NOT NULL,
  CONSTRAINT orders_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES customers (id)
);
CREATE INDEX orders_customer ON orders (customer_id);
CREATE VIEW order_totals AS SELECT c.name, count(o.id) AS orders, sum(o.total) AS total FROM customers c LEFT JOIN orders o ON o.customer_id = c.id GROUP BY c.name;
